3	// Coverage for the IPv6 form of the optional source network filter. The
4	// filter stays one-network-either-family: a parsed IPv6 network masks host
5	// bits and renders canonically (compressed or full input spelling alike),
6	// /128 admits one address and ::/0 every normalized IPv6 source, and an
7	// IPv6 network never admits an IPv4 source (the ::ffff: mapped family
8	// included) while an IPv4 network never admits an IPv6 source. Filtering
9	// still removes only successful events: failed lines keep their physical
10	// line number and reason regardless of address family.
11	
12	import (
13		"strings"
14		"testing"
15	)
16	
17	// TestParseSourceCIDRFilterIPv6Canonicalization pins host-bit masking and
18	// compressed/full spelling equivalence for the IPv6 grammar.
19	func TestParseSourceCIDRFilterIPv6Canonicalization(t *testing.T) {
20		cases := []struct {
21			in   string
22			want string
23		}{
24			{"2001:db8::/64", "2001:db8::/64"},
25			{"2001:db8::1234/64", "2001:db8::/64"}, // host bits masked away
26			{"2001:db8:0:0:0:0:0:1/64", "2001:db8::/64"},
27			{"2001:0db8:0000:0000:0000:0000:0000:0000/64", "2001:db8::/64"},
28			{"2001:db8::1/128", "2001:db8::1/128"},
29			{"::1/128", "::1/128"},
30			{"::/0", "::/0"},
31			{"fe80::abcd:1234/10", "fe80::/10"},
32			{"2001:db8:1:2:3:4:5:6/48", "2001:db8:1::/48"},
33			// ::192.0.2.1 is a genuine IPv6 address (not a mapping), so it is a
34			// legal IPv6 network; masked host bits render in hex.
35			{"::192.0.2.1/120", "::c000:200/120"},
36		}
37		for _, tc := range cases {
38			f, err := ParseSourceCIDRFilter(tc.in)
39			if err != nil {
40				t.Fatalf("ParseSourceCIDRFilter(%q) unexpected error: %v", tc.in, err)
41			}
42			if got := f.String(); got != tc.want {
43				t.Fatalf("ParseSourceCIDRFilter(%q).String() = %q, want %q", tc.in, got, tc.want)
44			}
45		}
46	}
47	
48	// TestParseSourceCIDRFilterIPv6Rejects pins the shapes the IPv6 grammar
49	// refuses: bad addresses, out-of-range or padded prefix lengths, ports and
50	// zones, and the IPv4-mapped family (which must be written as IPv4).
51	func TestParseSourceCIDRFilterIPv6Rejects(t *testing.T) {
52		bad := []string{
53			"2001:db8::/129",    // prefix too large
54			"2001:db8::/1000",   // pattern caps at three digits but value still out of range
55			"2001:db8::/-1",     // negative length
56			"2001:db8::/64x",    // trailing junk on the length
57			"2001:db8::/064",    // padded length
58			"2001:db8::/00",     // padded length
59			"2001:db8::1",       // no slash/length
60			"2001:db8::1/",      // empty length
61			"2001:db8::1/64/64", // extra segment
62			"1::2::3/64",        // two compression markers
63			"1:2:3:4:5:6:7:8:9/64",
64			"2001:db8::g1/64",              // non-hex group
65			"fe80::1%eth0/64",              // zone identifier
66			"[2001:db8::1]:443/64",         // brackets and port
67			" 2001:db8::1/64",              // leading space
68			"2001:db8::1/64 ",              // trailing space
69			"::ffff:192.0.2.0/120",         // IPv4-mapped: use the IPv4 network
70			"::ffff:c000:0201/120",         // mapped spelling in hex
71			"::ffff:0:0/96",                // the mapped prefix itself
72			"0:0:0:0:0:ffff:192.0.2.1/128", // mapped, full spelling
73		}
74		for _, in := range bad {
75			if f, err := ParseSourceCIDRFilter(in); err == nil {
76				t.Fatalf("ParseSourceCIDRFilter(%q) must fail, got filter %s", in, f)
77			}
78		}
79		// Legal boundary addresses/lengths that the reject list must not sweep
80		// in: /0, /128, and a dotted-decimal tail that is a genuine IPv6
81		// address (the last 32 bits, not an IPv4 mapping).
82		for _, ok := range []string{"2001:db8::/0", "2001:db8::/128", "2001:db8::1.2.3.4/64"} {
83			if _, err := ParseSourceCIDRFilter(ok); err != nil {
84				t.Fatalf("the boundary value %q must be accepted, got %v", ok, err)
85			}
86		}
87	}
88	
89	// TestParseSourceCIDRFilterIPv6MappedRejectionMessage ensures the mapped
90	// rejection points the caller at the IPv4 spelling rather than silently
91	// converting the prefix.
92	func TestParseSourceCIDRFilterIPv6MappedRejectionMessage(t *testing.T) {
93		_, err := ParseSourceCIDRFilter("::ffff:192.0.2.0/120")
94		if err == nil {
95			t.Fatal("an IPv4-mapped network must be rejected")
96		}
97		msg := err.Error()
98		if !strings.Contains(msg, "IPv4-mapped") || !strings.Contains(msg, "IPv4 network") {
99			t.Fatalf("rejection must explain the mapped family and its IPv4 spelling, got %q", msg)
100		}
101	}
