103	// TestSourceCIDRFilterIPv6AdmitsNormalized checks the IPv6 membership
104	// function against the exact strings normalization emits, including the
105	// family boundary in both directions and the address extremes.
106	func TestSourceCIDRFilterIPv6AdmitsNormalized(t *testing.T) {
107		block, err := ParseSourceCIDRFilter("2001:db8::1234/64")
108		if err != nil {
109			t.Fatal(err)
110		}
111		if got := block.String(); got != "2001:db8::/64" {
112			t.Fatalf("host bits must be masked in the rendered network, got %q", got)
113		}
114		host, err := ParseSourceCIDRFilter("2001:db8::abcd/128")
115		if err != nil {
116			t.Fatal(err)
117		}
118		all, err := ParseSourceCIDRFilter("::/0")
119		if err != nil {
120			t.Fatal(err)
121		}
122	
123		inside := []string{
124			"2001:db8::", "2001:db8::1", "2001:db8::1234",
125			"2001:db8:0:0:0:0:0:1", "2001:db8::ffff:ffff:ffff:ffff",
126		}
127		outside := []string{
128			"2001:db8:1::1", "fe80::1", "::1",
129			// An IPv4 source never matches an IPv6 network even via the mapped
130			// spelling it normalized from.
131			"192.0.2.1",
132		}
133		for _, ip := range inside {
134			if !block.admits(ip) {
135				t.Errorf("/64 must admit %q", ip)
136			}
137			if !all.admits(ip) {
138				t.Errorf("::/0 must admit IPv6 %q", ip)
139			}
140			if ip != "2001:db8::abcd" && host.admits(ip) {
141				t.Errorf("/128 must not admit %q", ip)
142			}
143		}
144		if !host.admits("2001:db8::abcd") {
145			t.Error("/128 must admit exactly 2001:db8::abcd")
146		}
147		for _, ip := range outside {
148			if block.admits(ip) {
149				t.Errorf("/64 must not admit %q", ip)
150			}
151			if host.admits(ip) {
152				t.Errorf("/128 must not admit %q", ip)
153			}
154		}
155		// ::/0 covers every genuine IPv6 source but no normalized IPv4 one.
156		if !all.admits("::c000:201") {
157			t.Error("::/0 must admit the genuine IPv6 spelling ::c000:201")
158		}
159		for _, v4 := range []string{"192.0.2.1", "0.0.0.0", "255.255.255.255"} {
160			if all.admits(v4) {
161				t.Errorf("::/0 must not admit IPv4 source %q", v4)
162			}
163		}
164		// Absent source is the empty string; it is never admitted by either family.
165		for _, f := range []SourceCIDRFilter{block, host, all} {
166			if f.admits("") {
167				t.Errorf("an absent source_ip must never be admitted by %s", f)
168			}
169		}
170	}
171	
172	// TestSourceCIDRFilterFamilyBoundary pins cross-family non-matching in
173	// both directions using one pair of filters and sources.
174	func TestSourceCIDRFilterFamilyBoundary(t *testing.T) {
175		v4, err := ParseSourceCIDRFilter("192.0.2.0/24")
176		if err != nil {
177			t.Fatal(err)
178		}
179		// A genuine IPv6 network covering ::c000:201 (the normalized form of
180		// the IPv4-compatible spelling ::192.0.2.1).
181		v6, err := ParseSourceCIDRFilter("::/96")
182		if err != nil {
183			t.Fatal(err)
184		}
185		if !v6.admits("::c000:201") {
186			t.Error("::/96 must admit the genuine IPv6 source ::c000:201")
187		}
188		if v6.admits("192.0.2.1") {
189			t.Error("an IPv6 network must not admit normalized IPv4 192.0.2.1")
190		}
191		if v4.admits("::c000:201") {
192			t.Error("an IPv4 network must not admit genuine IPv6 ::c000:201")
193		}
194		if !v4.admits("192.0.2.1") {
195			t.Error("/24 must admit 192.0.2.1")
196		}
197	}
198	
199	// TestSourceCIDRFilterIPv6StreamBehavior covers the mixed stream under an
200	// IPv6 filter: in-range IPv6 successes (compressed, full, compatible-tail
201	// spellings) are emitted with unchanged content and line numbers; IPv4,
202	// mapped, out-of-range and absent successes are dropped silently; failures
203	// survive regardless of family and keep counting physical lines.
204	func TestSourceCIDRFilterIPv6StreamBehavior(t *testing.T) {
205		filter, err := ParseSourceCIDRFilter("2001:db8::5678/64")
206		if err != nil {
207			t.Fatal(err)
208		}
209		input := strings.Join([]string{
210			`{"timestamp":"2026-01-02T00:00:00Z","action":"in-compressed","source_ip":"2001:db8::1"}`,    // 1 admitted
211			`{"timestamp":"2026-01-02T00:00:00Z","action":"in-full","src_ip":"2001:db8:0:0:0:0:0:2"}`,    // 2 admitted via alias
212			`{"timestamp":"2026-01-02T00:00:00Z","action":"in-hostbits","source_ip":"2001:db8::ffff:f"}`, // 3 admitted
213			`{"timestamp":"2026-01-02T00:00:00Z","action":"other-v6","source_ip":"2001:db8:1::1"}`,       // 4 dropped
214			`{"timestamp":"2026-01-02T00:00:00Z","action":"plain-v4","source_ip":"192.0.2.1"}`,           // 5 dropped (family)
215			`{"timestamp":"2026-01-02T00:00:00Z","action":"mapped","source_ip":"::ffff:192.0.2.1"}`,      // 6 dropped (family)
216			`{"timestamp":"2026-01-02T00:00:00Z","action":"compat-in","source_ip":"::c000:201"}`,         // 7 dropped (outside)
217			`{"timestamp":"2026-01-02T00:00:00Z","action":"no-source"}`,                                  // 8 dropped (absent)
218			`{"timestamp":"bad","action":"failed-v6","source_ip":"2001:db8::9"}`,                         // 9 failure (in range)
219			`{"timestamp":"bad","action":"failed-v4","source_ip":"192.0.2.9"}`,                           // 10 failure (IPv4)
220			`{"timestamp":"bad","action":"failed-absent"}`,                                               // 11 failure
221			``, // 12 blank
222			`{"timestamp":"2026-01-02T00:00:00Z","action":"tail","source_ip":"2001:db8::abcd"}`, // 13 admitted
223		}, "\n") + "\n"
224	
225		results, failures := runNormalizeFiltered(t, input, &filter)
226	
227		if failures != 3 {
228			t.Fatalf("the three malformed lines must count as failures even under an IPv6 filter, got %d", failures)
229		}
230		if len(results) != 7 {
231			t.Fatalf("expected 4 admitted successes + 3 failures = 7 records, got %d: %#v", len(results), results)
232		}
233		type expected struct {
234			line float64
235			ok   bool
236			mark string
237		}
238		want := []expected{
239			{1, true, "in-compressed"},
240			{2, true, "in-full"},
241			{3, true, "in-hostbits"},
242			{9, false, "failed-v6"},
243			{10, false, "failed-v4"},
244			{11, false, "failed-absent"},
245			{13, true, "tail"},
246		}
247		for i, w := range want {
248			got := results[i]
249			if got["line"] != w.line || got["ok"] != w.ok {
250				t.Fatalf("record %d mismatch: want line=%v ok=%v, got %#v", i, w.line, w.ok, got)
251			}
252			if w.ok {
253				if eventOf(t, got)["action"] != w.mark {
254					t.Fatalf("record %d action mismatch: %#v", i, got)
255				}
256			} else {
257				if _, exists := got["event"]; exists {
258					t.Fatalf("failed record %d must not carry an event: %#v", i, got)
259				}
260				if msg, _ := got["error"].(string); !strings.Contains(msg, FieldTimestamp) {
261					t.Fatalf("failed record %d must keep its original reason, got %q", i, msg)
262				}
263			}
264		}
265	}
266	
267	// TestSourceCIDRFilterIPv6ColonZeroAllAndOne pins ::/0 and /128 behavior
268	// through the streaming entry point, including equivalence spellings of
269	// the one /128 address.
270	func TestSourceCIDRFilterIPv6ColonZeroAndOneTwoEight(t *testing.T) {
271		exact, err := ParseSourceCIDRFilter("::1/128")
272		if err != nil {
273			t.Fatal(err)
274		}
275		input := strings.Join([]string{
276			`{"timestamp":"2026-01-02T00:00:00Z","action":"loopback","source_ip":"0:0:0:0:0:0:0:1"}`,
277			`{"timestamp":"2026-01-02T00:00:00Z","action":"other-v6","source_ip":"2001:db8::1"}`,
278			`{"timestamp":"2026-01-02T00:00:00Z","action":"v4","source_ip":"192.0.2.1"}`,
279			`{"timestamp":"2026-01-02T00:00:00Z","action":"none"}`,
280		}, "\n") + "\n"
281	
282		results, failures := runNormalizeFiltered(t, input, &exact)
283		if failures != 0 || len(results) != 1 {
284			t.Fatalf("/128 must keep only the full-spelling loopback, got %#v failures=%d", results, failures)
285		}
286		if eventOf(t, results[0])["source_ip"] != "::1" {
287			t.Fatalf("full spelling must normalize to ::1: %#v", results[0])
288		}
289	
290		all, err := ParseSourceCIDRFilter("::/0")
291		if err != nil {
292			t.Fatal(err)
293		}
294		results, failures = runNormalizeFiltered(t, input, &all)
295		if failures != 0 || len(results) != 2 {
296			t.Fatalf("::/0 must keep both IPv6 events but no IPv4 or absent source, got %#v failures=%d", results, failures)
297		}
298		for _, r := range results {
299			if !strings.Contains(eventOf(t, r)["source_ip"].(string), ":") {
300				t.Fatalf("::/0 must not admit an IPv4 source: %#v", r)
301			}
302		}
303	}
