225			validCIDRSource("kept", "2001:db8::1") + "\n"
226		cases := []struct {
227			name       string
228			args       []string
229			wantInText string
230		}{
231			{"prefix 129", []string{"--source-cidr", "2001:db8::/129"}, "out of range"},
232			{"prefix 1000", []string{"--source-cidr", "2001:db8::/1000"}, "must be an IP network"},
233			{"padded prefix", []string{"--source-cidr", "2001:db8::/064"}, "leading zero"},
234			{"bad compression", []string{"--source-cidr", "1::2::3/64"}, "invalid IPv6"},
235			{"non-hex group", []string{"--source-cidr=2001:db8::g/64"}, "invalid IPv6"},
236			{"zone id", []string{"--source-cidr", "fe80::1%eth0/64"}, "invalid IPv6"},
237			{"bracketed port", []string{"--source-cidr", "[2001:db8::1]:443/64"}, "invalid IPv6"},
238			{"no slash", []string{"--source-cidr", "2001:db8::1"}, "must be an IP network"},
239			{"mapped network", []string{"--source-cidr", "::ffff:192.0.2.0/120"}, "IPv4 network"},
240			{"mapped network attached", []string{"--source-cidr=::ffff:c000:201/128"}, "IPv4 network"},
241			{"duplicate", []string{"--source-cidr", "2001:db8::/64", "--source-cidr=fe80::/10"}, "at most once"},
242			{"duplicate across families", []string{"--source-cidr=192.0.2.0/24", "--source-cidr", "2001:db8::/64"}, "at most once"},
243			{"empty value", []string{"--source-cidr", ""}, "must be an IP network"},
244			{"empty attached", []string{"--source-cidr="}, "must be an IP network"},
245		}
246		for _, tc := range cases {
247			t.Run(tc.name, func(t *testing.T) {
