249				if result.exitCode != 2 {
250					t.Fatalf("bad option must exit 2, got %d (stdout %q stderr %q)", result.exitCode, result.stdout, result.stderr)
251				}
252				if result.stdout != "" {
253					t.Fatalf("a parameter error must leave stdout empty and must not process stdin, got %q", result.stdout)
254				}
255				if !strings.HasPrefix(result.stderr, "normalize: ") {
256					t.Fatalf("diagnostic must carry the normalize: prefix, got %q", result.stderr)
257				}
258				if !strings.Contains(result.stderr, "source-cidr") {
259					t.Fatalf("diagnostic should name the option, got %q", result.stderr)
260				}
261				if !strings.Contains(result.stderr, tc.wantInText) {
262					t.Fatalf("diagnostic should contain %q, got %q", tc.wantInText, result.stderr)
263				}
264			})
265		}
266	}
