268	// A legitimate IPv6 filter keeps surviving records byte-identical to an
269	// unfiltered run: selection changes nothing about the emitted JSON.
270	func TestNormalizeCLISourceCIDRIPv6OutputMatchesUnfiltered(t *testing.T) {
271		input := strings.Join([]string{
272			validCIDRSource("in", "2001:db8::7"),
273			validCIDRSource("out", "fe80::1"),
274		}, "\n") + "\n"
275	
276		filtered := runNormalizeCLIArgs(t, strings.NewReader(input), "--source-cidr", "2001:db8::/64")
277		unfiltered := runNormalizeCLI(t, strings.NewReader(validCIDRSource("in", "2001:db8::7")+"\n"))
278		if filtered.exitCode != 0 || unfiltered.exitCode != 0 {
279			t.Fatalf("both runs must exit 0, got %d and %d", filtered.exitCode, unfiltered.exitCode)
280		}
281		if filtered.stdout != unfiltered.stdout {
282			t.Fatalf("kept record must be identical with and without the filter:\nfiltered:   %s\nunfiltered: %s",
283				filtered.stdout, unfiltered.stdout)
284		}
285	}
