1	package main
2	
3	// CLI-level regression coverage for source networks whose prefix length does
4	// not fall on an IPv4 octet boundary, exercised against the real compiled
5	// binary. 172.16.5.9/12 admits exactly 172.16.0.0 - 172.31.255.255 and
6	// 192.0.129.7/17 admits exactly 192.0.128.0 - 192.0.255.255: both range ends
7	// survive, the addresses immediately outside each range do not, and a
8	// boundary source works through source_ip and src_ip alike, with plain IPv4
9	// and its ::ffff: mapping sharing one decision and one dotted output form
10	// while genuine IPv6 with the same trailing bits never matches. The
11	// two-address network 192.0.2.3/31 keeps both 192.0.2.2 and 192.0.2.3 — no
12	// network/broadcast exclusion — and spelling it as 192.0.2.2/31 selects
13	// byte-identically. An out-of-range log with an invalid timestamp is still a
14	// counted failure with its reason and no event, later in-range logs keep
15	// coming with their physical line numbers, and a batch in which every valid
16	// log misses the network exits 0 with empty output.
17	
18	import (
19		"strings"
20		"testing"
21	)
22	
23	// The /12 and /17 ranges through the CLI: first and last range addresses are
24	// kept with their physical line numbers and normalized dotted sources, the
25	// adjacent addresses, a genuine IPv6 look-alike and an absent source are
26	// dropped silently, and the run stays clean (exit 0, stderr empty, no filter
27	// marker on any record).
28	func TestNormalizeCLISourceCIDRNonOctetBoundaries(t *testing.T) {
29		cases := []struct {
30			name   string
31			option string
32			// lines holds (source field, source address) pairs; kept marks the
33			// ones the network must admit.
34			lines []struct {
35				field string
36				addr  string
37				kept  bool
38			}
39		}{
40			{
41				name:   "second-octet boundary /12",
42				option: "172.16.5.9/12",
43				lines: []struct {
44					field string
45					addr  string
46					kept  bool
47				}{
48					{"source_ip", "172.16.0.0", true},        // first address of the range
49					{"src_ip", "172.31.255.255", true},       // last address, via the alias
50					{"source_ip", "::ffff:172.16.0.0", true}, // mapped spelling of the first address
51					{"source_ip", "172.15.255.255", false},   // immediately below
52					{"source_ip", "172.32.0.0", false},       // immediately above
53					{"source_ip", "::172.16.0.0", false},     // genuine IPv6 with an in-range tail
54					{"", "", false},                          // absent source
55				},
56			},
57			{
58				name:   "third-octet boundary /17",
59				option: "192.0.129.7/17",
60				lines: []struct {
61					field string
62					addr  string
63					kept  bool
64				}{
65					{"source_ip", "192.0.128.0", true},          // first address of the range
66					{"src_ip", "192.0.255.255", true},           // last address, via the alias
67					{"source_ip", "::ffff:192.0.255.255", true}, // mapped spelling of the last address
68					{"source_ip", "192.0.127.255", false},       // immediately below
69					{"source_ip", "192.1.0.0", false},           // immediately above
70					{"source_ip", "::192.0.128.0", false},       // genuine IPv6 with an in-range tail
71					{"", "", false},                             // absent source
72				},
73			},
74		}
75	
76		for _, tc := range cases {
77			t.Run(tc.name, func(t *testing.T) {
78				var inputLines []string
79				var want []struct {
80					line   float64
81					action string
82					source string
83				}
84				for i, l := range tc.lines {
85					action := l.addr
86					if action == "" {
87						action = "no-source"
88					}
89					var line string
90					if l.field == "" {
91						line = `{"timestamp":"2026-01-02T00:00:00Z","action":"` + action + `"}`
92					} else {
93						line = `{"timestamp":"2026-01-02T00:00:00Z","action":"` + action + `","` + l.field + `":"` + l.addr + `"}`
94					}
95					inputLines = append(inputLines, line)
96					if l.kept {
97						want = append(want, struct {
98							line   float64
99							action string
100							source string
101						}{float64(i + 1), action, strings.TrimPrefix(l.addr, "::ffff:")})
102					}
103				}
104				input := strings.Join(inputLines, "\n") + "\n"
105	
106				result := runNormalizeCLIArgs(t, strings.NewReader(input), "--source-cidr", tc.option)
107				if result.exitCode != 0 {
108					t.Fatalf("a fully valid, partially filtered stream must exit 0, got %d (stderr: %q)",
109						result.exitCode, result.stderr)
110				}
111				if result.stderr != "" {
112					t.Fatalf("filtering successes needs no diagnostics, got %q", result.stderr)
113				}
114	
115				results := decodeStdoutResults(t, result.stdout)
116				if len(results) != len(want) {
117					t.Fatalf("expected %d admitted records, got %#v", len(want), results)
118				}
119				for i, w := range want {
120					got := results[i]
121					if got["line"] != w.line || got["ok"] != true {
122						t.Fatalf("record %d must keep physical line %v and ok:true: %#v", i, w.line, got)
123					}
124					if _, marked := got["filtered"]; marked {
125						t.Fatalf("record %d must carry no filter marker: %#v", i, got)
126					}
127					event := eventOf(t, got)
128					if event["action"] != w.action || event["source_ip"] != w.source {
129						t.Fatalf("record %d event mismatch: %#v", i, event)
130					}
131				}
132			})
133		}
134	}
135	
136	// The /31 two-address network through the CLI: both addresses of the pair
137	// survive — neither is treated as a network or broadcast address — the
