	}
	outside := []string{
		"2001:db8:1:2:ab7f:ffff:ffff:ffff", // immediately below the range
		"2001:db8:1:2:ac00::",              // immediately above the range
		"2001:db8:1:3::1",                  // a different network entirely
	}
